import json
import sys
from operator import itemgetter

def main():
    if len(sys.argv) < 2:
        print("Usage: python bookmark_manager.py <json_file>")
        return

    json_file = sys.argv[1]
    try:
        with open(json_file, 'r') as file:
            bookmarks = json.load(file)
    except FileNotFoundError:
        bookmarks = []

    while True:
        print("\nBookmark Manager")
        print("1. Add name and URL")
        print("2. List bookmarks")
        print("3. Remove bookmark")
        print("4. Exit")
        choice = input("Enter your choice: ")

        if choice == "1":
            name = input("Enter name: ")
            url = input("Enter URL: ")
            bookmarks.append({"name": name, "url": url})
        elif choice == "2":
            bookmarks.sort(key=itemgetter("name"))
            for bookmark in bookmarks:
                print(f"{bookmark['name']}\t{bookmark['url']}")
        elif choice == "3":
            name = input("Enter name to remove: ")
            bookmarks = [bookmark for bookmark in bookmarks if bookmark["name"] != name]
        elif choice == "4":
            print("Exiting bookmark manager")
            return
        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    main()

import sys


def main():
    board = [" " for _ in range(9)]
    current_player = "X"
    while True:
        print_board(board)
        move = input(f"Player {current_player}, enter your move (1-9): ")
        if move.isdigit() and 1 <= int(move) <= 9 and board[int(move) - 1] == " ":
            board[int(move) - 1] = current_player
            if check_winner(board, current_player):
                print_board(board)
                print(f"Player {current_player} wins!")
                return
            if is_draw(board):
                print_board(board)
                print("It's a draw!")
                return
            current_player = "O" if current_player == "X" else "X"
        else:
            print("Invalid move. Please try again.")


def print_board(board):
    for i in range(3):
        print(" ".join(board[i * 3 : (i + 1) * 3]))
    print()


def check_winner(board, player):
    return (board[0] == board[1] == board[2] == player or
            board[3] == board[4] == board[5] == player or
            board[6] == board[7] == board[8] == player or
            board[0] == board[3] == board[6] == player or
            board[1] == board[4] == board[7] == player or
            board[2] == board[5] == board[8] == player or
            board[0] == board[4] == board[8] == player or
            board[2] == board[4] == board[6] == player)


def is_draw(board):
    return all(board[i] != " " for i in range(9))


if __name__ == "__main__":
    main()

import os
import json
import argparse

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("directory", help="directory to inventory")
    parser.add_argument("--suffix", help="suffix to filter files by")
    args = parser.parse_args()

    inventory = inventory_directory(args.directory, args.suffix)
    print(json.dumps(inventory, indent=4))

def inventory_directory(directory, suffix=None):
    inventory = {}
    for root, dirs, files in os.walk(directory):
        for file in files:
            if suffix and not file.endswith(suffix):
                continue
            path = os.path.join(root, file)
            inventory[path] = os.path.getsize(path)
    return inventory

if __name__ == "__main__":
    main()

import argparse
import json
import sys


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("input", type=argparse.FileType("r"))
    args = parser.parse_args()

    total = 0
    for line_number, line in enumerate(args.input, start=1):
        try:
            transaction = json.loads(line)
            if not isinstance(transaction, dict) or "id" not in transaction or "cents" not in transaction:
                raise ValueError("Invalid transaction format")
            if not isinstance(transaction["id"], str) or not isinstance(transaction["cents"], int):
                raise ValueError("Invalid transaction values")
            if transaction["id"] == "":
                raise ValueError("Transaction id cannot be empty")
            if transaction["cents"] <= 0:
                raise ValueError("Transaction cents must be positive")
            total += transaction["cents"]
        except json.JSONDecodeError:
            print(f"Error decoding line {line_number}: {line}", file=sys.stderr)
            return 1

    print(total)


if __name__ == "__main__":
    main()

import json
import sys

def main():
    if len(sys.argv) != 2:
        print("Usage: python quiz.py <quiz_file>")
        return

    quiz_file = sys.argv[1]
    try:
        with open(quiz_file, 'r') as file:
            quiz = json.load(file)
    except FileNotFoundError:
        print(f"Error: {quiz_file} not found")
        return

    score = 0
    for question in quiz:
        print(question["question"])
        for answer in question["answers"]:
            print(answer)
            user_answer = input().strip().lower()
            if user_answer == question["correct_answer"].lower():
                score += 1
    print(f"Score: {score}/{len(quiz)}")

if __name__ == "__main__":
    main()
